describe('Data Reviewer - Table Row and Column Exposure', () => {
  beforeEach(() => {
    cy.visit('/tables');
  });

  it('should verify table header contains correct column headings and table body contains 4 rows', () => {
    cy.get('[data-testid="table1"]').should('be.visible');
    cy.get('[data-testid="table1"]').should('have.attr', 'aria-label', 'Table 1');

    cy.get('[data-testid="table1"]').within(() => {
      cy.get('[data-testid="table-header"]').should('be.visible');
      cy.get('[data-testid="table-header"]').should('contain', 'Last Name');
      cy.get('[data-testid="table-header"]').should('contain', 'First Name');
      cy.get('[data-testid="table-header"]').should('contain', 'Email');
      cy.get('[data-testid="table-header"]').should('contain', 'Due');
    });

    cy.get('[data-testid="table1"]').within(() => {
      cy.get('[data-testid="table-body"]').should('be.visible');
      cy.get('[data-testid="table-body"]').should('contain', 4);
    });
  });

  it('should verify a row contains the correct email and last name', () => {
    cy.get('[data-testid="table1"]').within(() => {
      cy.get('[data-testid="table-body"]').each(($row) => {
        cy.wrap($row).should('be.visible');
        cy.wrap($row).within(() => {
          cy.get('[data-testid="cell-last-name"]').should('contain', 'Smith');
          cy.get('[data-testid="cell-email"]').should('contain', 'jsmith@gmail.com');
        });
      });
    });
  });

  it('should verify table does not contain duplicate rows', () => {
    cy.get('[data-testid="table1"]').within(() => {
      cy.get('[data-testid="table-body"]').each(($row) => {
        cy.wrap($row).within(() => {
          cy.get('[data-testid="cell-last-name"]').then((cell) => {
            const lastName = cell.text().trim();
            cy.get('[data-testid="table-body"]').then(($rows) => {
              const existingLastNames = $rows.map((row) => {
                cy.wrap(row).within(() => {
                  cy.get('[data-testid="cell-last-name"]').then((cell) => {
                    return cell.text().trim();
                  });
                }).invoke('text').then((text) => {
                  return text.trim();
                });
              }).get();
              if (existingLastNames.includes(lastName)) {
                cy.get('[data-testid="table-body"]').then(($rows) => {
                  cy.wrap($rows).each(($row) => {
                    cy.wrap($row).within(() => {
                      cy.get('[data-testid="cell-last-name"]').then((cell) => {
                        cy.wrap(cell).should('contain', lastName);
                      });
                    });
                  });
                });
              }
            });
          });
        });
      });
    });
  });
});
